async def _stream_and_collect(aclient, **kwargs):
    """Stream a Claude call and return the final Message object.

    Used instead of aclient.messages.create() for large-token calls that would
    exceed the Anthropic SDK's 10-minute non-streaming limit (e.g. Opus 4.5
    with max_tokens=64000).  Returns the same Message object as .create().
    Retries automatically on transient API errors (429, 500, 503, overloaded).
    """
    from services.api_retry import async_api_call_with_retry
    async def _call():
        async with aclient.messages.stream(**kwargs) as strm:
            return await strm.get_final_message()
    return await async_api_call_with_retry(_call)



# ── Phase 3: shared parse helpers (used by both mid-stream + EOS) ──────

def _looks_like_filename(cand: str) -> bool:
    """True when `cand` plausibly names a file the model wants pulled, rather
    than a line of prose.

    Proven bug (screenshot 2026-07-20): when <file_request> content is not
    valid JSON, the plain-text fallback below split it on commas/newlines and
    treated EVERY fragment as a filename — so a markdown bullet like
    "- **Tell me the branch name** … (I can use `diff_branches`)" rendered as a
    bogus "file needed" card. A real requested name is a short, path-safe token
    that either ends in an extension (AuthGate.jsx) or is a single bare token
    (Makefile, src/config). Prose — spaces + punctuation, markdown, no
    extension — is rejected."""
    cand = (cand or "").strip()
    if not cand or len(cand) > 200 or "\n" in cand:
        return False
    # Reject obvious markdown / prose markers.
    if any(tok in cand for tok in ("**", "`", "→", ": ", "?", "(", ")", "  ")):
        return False
    if cand[:2] in ("- ", "* ", "# ") or cand.startswith("#"):
        return False
    # (a) has a file extension and is path-safe, or
    if re.search(r"\.[A-Za-z0-9]{1,8}$", cand) and re.fullmatch(r"[\w\-./@ ]{1,200}", cand):
        return True
    # (b) a single bare path-safe token (Makefile, Dockerfile, src/config)
    if re.fullmatch(r"[\w\-./]{1,60}", cand):
        return True
    return False


def _parse_filereq_content(raw: str) -> list:
    """Parse file_request tag content — JSON array/string with plain-text fallback."""
    raw = raw.strip()
    if not raw:
        return []
    try:
        parsed = json.loads(raw)
        if isinstance(parsed, list):
            return [str(f).strip() for f in parsed if str(f).strip()]
        elif isinstance(parsed, str):
            return [parsed.strip()]
        elif isinstance(parsed, dict):
            # Proven bug (session d8f0ed39, 2026-07-23): Claude sometimes emits
            # a JSON object shape here — matching the dict convention used by
            # <search_request>/<history_request> in the same instruction block
            # — instead of the documented array/string. Before this branch,
            # a dict was valid JSON but matched neither `list` nor `str`, so
            # it silently fell through to `return []` with NO log trace,
            # dropping a legitimate file request and starving the model mid-task.
            # Accept both {"filename": "x"} and {"filenames": [...]} so the
            # request is recovered instead of silently discarded.
            _names = []
            if isinstance(parsed.get("filenames"), list):
                _names = [str(f).strip() for f in parsed["filenames"] if str(f).strip()]
            elif parsed.get("filename"):
                _names = [str(parsed["filename"]).strip()]
            _dlog("filereq_dict_shape_recovered",
                  raw_preview=raw[:200],
                  recovered=_names[:10],
                  recovered_count=len(_names))
            return _names
        _dlog("filereq_unrecognized_json_shape",
              raw_preview=raw[:200],
              parsed_type=type(parsed).__name__)
        return []
    except (json.JSONDecodeError, ValueError):
        # Non-JSON fallback: split on commas/newlines, but keep only fragments
        # that actually look like filenames. Without this gate, prose the model
        # wrote around a malformed tag becomes phantom "file needed" cards.
        _cands = [f.strip() for f in raw.replace(",", "\n").split("\n") if f.strip()]
        _kept = [c for c in _cands if _looks_like_filename(c)]
        # Bug A probe (session f10e5b33): prove whether the filename gate is
        # rescuing us from phantom "file needed" cards. When candidates exist
        # but NONE survive the filename check, the tag content was prose — not
        # a file request — and returning [] is the correct, bug-killing outcome.
        _dlog("filereq_nonjson_fallback",
              raw_preview=raw[:200],
              raw_len=len(raw),
              cand_count=len(_cands),
              kept_count=len(_kept),
              kept=_kept[:10],
              rejected_as_prose=[c for c in _cands if not _looks_like_filename(c)][:10])
        return _kept


def _parse_search_content(raw: str):
    """Parse search_request tag content — JSON dict. Returns parsed dict or None."""
    try:
        return json.loads(raw.strip())
    except Exception:
        return None


def _parse_history_content(raw: str):
    """Parse history_request tag content — JSON dict {"filename": ..., "query": ...
    (optional)}. Returns a dict with at least "filename", or None if the tag
    body was not valid JSON / had no usable filename (mirrors
    _parse_search_content's fail-quiet-to-None style; the caller wraps a
    None return into an {"_invalid": ...} recovery message, same as search/
    filereq/github)."""
    try:
        parsed = json.loads(raw.strip())
    except Exception:
        return None
    if not isinstance(parsed, dict):
        return None
    filename = str(parsed.get("filename", "")).strip()
    if not filename:
        return None
    query = parsed.get("query")
    query = str(query).strip() if query else None
    return {"filename": filename, "query": query}


def pick_no_edits_notice(
    hit_agent_max_turns: bool,
    has_skipped_changes: bool,
    normal_buf: str,
    full_response: str,
    agent_max_turns: int,
):
    """Choose the right "no code changes" notice to show the user when an
    agent-mode turn ends with zero edit blocks and zero skipped-plan-items.

    Returns (event_name_for_dlog, message_or_None). message is None when
    nothing should be shown (caller still yields the "done" event).

    Proven bug (session 6930f196): `full_response` is reset every turn (it's
    the LAST turn's transcript only — see the per-turn state reset in the
    main loop) and can contain raw, un-executed <search_request>/<filereq>/
    <github> tag text that was NEVER streamed to the user — only
    `normal_buf` is actually sent as "token" SSE events. The old code
    checked `full_response.strip()` and unconditionally said "the response
    above was a plan/explanation only," which is false when the cutoff
    happened mid-tool-call (e.g. AGENT_MAX_TURNS hit while composing a
    <search_request>). This function picks an honest, specific message
    instead, distinguishing:
      1. Ran out of turns entirely (mid-search) -> say so explicitly.
      2. Real user-visible prose exists (normal_buf) -> the old "plan only" msg.
      3. Cut off some other way with no real prose to show -> honest fallback.
      4. Nothing at all -> no notice (caller just sends "done").
    """
    if hit_agent_max_turns:
        return "no_edits_max_turns_notice", (
            f"\n\n⚠️ I ran out of turns ({agent_max_turns}) while still "
            "searching/reading files and never got to write an edit. "
            "Try pointing me directly at the specific file and "
            "function/section to change — that skips the search step "
            "and leaves more turns for the actual edit."
        )
    if normal_buf.strip():
        return "no_edits_text_only_notice", (
            "\n\n⚠️ No code changes were produced — the response above "
            "was a plan/explanation only.  Please try again and I'll "
            "apply the edits directly."
        )
    if full_response.strip():
        return "no_edits_notext_notice", (
            "\n\n⚠️ No code changes were produced and I ran out of time "
            "before finishing my search. Try a more specific request "
            "(exact file + function) so I can skip straight to editing."
        )
    return "no_edits_silent", None


def resolve_file_request_batch(
    fnames_req,
    requested_files,
    user_supplied_files,
    same_name_retries,
    max_same_file_retries: int = 1,
    max_file_req_total: int = 15,
):
    """Decide which of the model's `<filereq>` filenames actually need a
    fresh fetch this turn, vs. which are already resolved (successfully OR
    definitively not-found) and must not trigger another search/HITL pause.

    Returns (new_fnames, rerequestable, hit_total_limit):
      new_fnames      -- filenames to actually go fetch this turn.
      rerequestable   -- subset of new_fnames that are a same-name
                         correction retry (earlier copy came from a user
                         upload and may be the WRONG file).
      hit_total_limit -- True when the distinct-file request budget is
                         exhausted and at least one of fnames_req is new.

    Proven bug this guards against (session e3f0e267, useRateCardHooks.js):
    a filename that could never be resolved (GitHub search exhausted, then
    the human-in-the-loop pause timed out with no upload) must still count
    as "requested" -- i.e. the CALLER must add it to `requested_files` even
    on failure. If the caller only records successes, the same never-found
    filename slips back through this filter on every later turn and pays a
    full new search + up to a 240s blocking pause EACH time, burning the
    whole streaming-phase time budget on a file that will never arrive and
    aborting before any edit is attempted. This function only enforces the
    filtering side of the contract; `requested_files.add(fn)` must be
    called for every outcome (found, not-found, skipped, timed out).
    """
    rerequestable = {
        fn for fn in fnames_req
        if fn in requested_files
        and fn in user_supplied_files
        and same_name_retries.get(fn, 0) < max_same_file_retries
    }
    new_fnames = [
        fn for fn in fnames_req
        if fn not in requested_files or fn in rerequestable
    ]
    new_distinct = [fn for fn in fnames_req if fn not in requested_files]
    hit_total_limit = (
        len(requested_files) >= max_file_req_total and bool(new_distinct))
    return new_fnames, rerequestable, hit_total_limit


def check_filereq_hard_limit(fnames_req, file_req_hard_counts, max_hard_retries: int = 4):
    """Hard circuit-breaker for `<file_request>` filenames, independent of
    `resolve_file_request_batch`'s requested-files bookkeeping.

    Increments a per-filename lifetime request counter and returns the
    filenames that have now been requested MORE than `max_hard_retries`
    times in this run, regardless of whether `requested_files` /
    `same_name_retries` believe the file was already resolved.

    This exists as defense-in-depth for the class of bug proven in session
    e3f0e267 (see `resolve_file_request_batch`'s docstring): if any future
    code path ever adds a filename to `fnames_req` without going through
    `resolve_file_request_batch`'s tracking correctly (a new branch, a
    renamed variable, an early `continue` before `requested_files.add`),
    this counter still trips and forces the loop to stop re-asking — it
    counts raw appearances of a filename in the model's `<file_request>`
    tag directly, rather than relying on any OTHER function's bookkeeping
    to have run correctly first. Two independent guards must both fail for
    an infinite re-ask loop to recur.

    Mutates `file_req_hard_counts` in place (caller owns the dict so it
    persists across turns). Returns the filenames that just crossed the
    limit on THIS call, order-preserving, de-duped.
    """
    tripped = []
    seen = set()
    for fn in fnames_req:
        file_req_hard_counts[fn] = file_req_hard_counts.get(fn, 0) + 1
        if file_req_hard_counts[fn] > max_hard_retries and fn not in seen:
            tripped.append(fn)
            seen.add(fn)
    return tripped


_FILEREQ_EXT_SWAP = {"ts": "tsx", "tsx": "ts", "js": "jsx", "jsx": "js"}
_FILEREQ_BARREL_NAMES = ("index.ts", "index.tsx", "index.js", "index.jsx")


def build_filereq_search_variants(fn: str):
    """Build an ordered list of GitHub `filename:` search-query variants to try
    for a requested filename `fn`, plus how to validate each variant's hits.

    Proven necessary against real repo data (session 6930f196): the model
    asked for "lib/fileClassify.ts" (real file is
    "frontend/src/lib/fileClassify.tsx" — .ts vs .tsx) and "types.ts" (real
    file is "frontend/src/types/index.ts" — an index-barrel), and the old
    single-shot exact-match search returned/matched nothing for either.

    Returns a list of (query_basename, acceptable_basenames, allow_barrel)
    tuples, in the order they should be tried. Stop at the first variant
    whose search actually returns a matching path.
    """
    base = fn.split("/")[-1]
    stem, dot, ext = base.rpartition(".")
    swapped_ext = _FILEREQ_EXT_SWAP.get(ext) if dot else None
    swapped_base = f"{stem}.{swapped_ext}" if swapped_ext else None

    # Accept either the requested extension or its swapped sibling on the
    # "as given" / "bare basename" queries — GitHub's filename: qualifier can
    # (and does, verified live) return a hit whose real extension differs
    # from what was requested (e.g. asked "fileClassify.ts", found
    # "fileClassify.tsx") on the very first, unmodified query.
    _primary_ok_bases = {base, swapped_base} if swapped_base else {base}

    # 1) Try the request as given first — GitHub's filename: qualifier
    #    matches on path suffix, so a correct directory hint helps narrow
    #    results even though we only validate the basename below.
    variants = [(fn, _primary_ok_bases, False)]
    if fn != base:
        # 2) fn had a (possibly wrong) directory prefix — also try the bare
        #    basename in case the guessed subdir was itself wrong.
        variants.append((base, _primary_ok_bases, False))
    if swapped_base:
        # 3) Extension variant (.ts<->.tsx, .js<->.jsx) as its own query, in
        #    case the as-given/basename queries returned nothing at all.
        variants.append((swapped_base, {swapped_base}, False))
    if dot:
        # 4) index-barrel: requested "X.ts" may really be a folder "X/" whose
        #    entry point is "X/index.ts" (or .tsx/.js/.jsx)
        variants.append((f"{stem}/index.ts", set(), True))
        variants.append((f"{stem}/index.tsx", set(), True))
    return variants


def filereq_path_matches(path: str, acceptable_basenames: set, allow_barrel: bool, stem: str) -> bool:
    """Check whether a GitHub search-result `path` counts as a real match for
    a file-request variant. Compares basenames (not full paths — a requested
    name never includes the repo's directory structure), and separately
    recognizes the index-barrel pattern ("<stem>/index.ts" etc.)."""
    result_base = path.split("/")[-1]
    if result_base in acceptable_basenames:
        return True
    if allow_barrel:
        parts = path.rsplit("/", 1)
        if len(parts) == 2:
            parent_name = parts[0].rsplit("/", 1)[-1]
            if parent_name == stem and parts[1] in _FILEREQ_BARREL_NAMES:
                return True
    return False


def _parse_plan_content(raw: str):
    """Parse edit_plan tag content — JSON list. Returns list or None."""
    try:
        result = json.loads(raw.strip())
        return result if isinstance(result, list) else None
    except Exception:
        return None


def _recover_stopped_plan_tag(full_response: str, tag_buf: str,
                               plan_open: str = "<edit_plan>"):
    """Recover an ``<edit_plan>`` whose closing tag was swallowed by the
    Anthropic ``stop_sequence`` mechanism instead of appearing in the
    stream text.

    Proven root cause (session d8f0ed39, turn 4): the model finished a
    complete, valid plan, the API halted the stream exactly at
    ``</edit_plan>`` (``state_at_halt: "in_plan"``), and the per-turn
    recovery step only handled ``search``/``filereq``/``github``/``history``
    tags — "plan" was missing. The finished plan was thrown away and the
    model was falsely told it "did not produce any code changes", wasting
    an entire extra turn of thinking before the phase deadline fired.

    Returns the parsed plan (a list) if the content between ``plan_open``
    and end-of-response parses as valid JSON, else ``None``. Never raises.
    """
    match = re.search(re.escape(plan_open) + r"(.*)", full_response, re.DOTALL)
    body = match.group(1) if match else tag_buf
    return _parse_plan_content(body)


def _looks_like_edit_block(text: str) -> bool:
    """True when `text` plausibly holds a JSON edit / new-file payload rather
    than prose.

    A real edit block always carries JSON structure with at least one
    recognised edit field. Model prose that merely *mentions* a tag name — e.g.
    a refusal written as "a `<surgical_edit>` against this file would mean
    guessing" — never does.

    Proven bug (session f10e5b33, AuthGate.jsx): the streaming tag scanner
    opened `in_edit` on a `<surgical_edit>` marker the model typed inside
    backticks in a `<blocked>` clarification; EOS recovery then kept the
    trailing prose as a phantom edit block, which failed JSON parse and was
    mislabelled "truncated — hit token limit" before a degenerate_drop. This
    guard lets recovery reject such prose so the real clarification is surfaced
    instead of a phantom edit. Real edits are always JSON, so they always pass."""
    if not text or "{" not in text:
        return False
    return bool(re.search(
        r'"(filename|new_code|old_code|symbol|edit_start_line|content)"\s*:',
        text,
    ))


def _eos_recover_blocks(open_tag: str, close_tag: str, full_response: str,
                        tag_buf: str, blocks_list: list) -> tuple:
    """EOS recovery: findall complete blocks in full_response, dedup, keep partial.
    Mutates blocks_list in place.
    Returns (new_count, partial_kept, had_matches, rejected_prose).
    rejected_prose is the leaked buffer text when it was NOT a plausible edit
    block (so the caller can surface it as prose instead of shipping a phantom
    edit); None otherwise."""
    pattern = re.escape(open_tag) + r"(.*?)" + re.escape(close_tag)
    all_matches = re.findall(pattern, full_response, re.DOTALL)
    new_count = 0
    partial_kept = False
    rejected_prose = None
    if all_matches:
        for block in all_matches:
            if block in blocks_list:
                continue
            if _looks_like_edit_block(block):
                blocks_list.append(block)
                new_count += 1
            elif rejected_prose is None:
                rejected_prose = block
        if (tag_buf.strip()
                and close_tag not in tag_buf
                and tag_buf not in blocks_list):
            if _looks_like_edit_block(tag_buf):
                blocks_list.append(tag_buf)
                partial_kept = True
            elif rejected_prose is None:
                rejected_prose = tag_buf
    else:
        if tag_buf.strip():
            if _looks_like_edit_block(tag_buf):
                blocks_list.append(tag_buf)
            else:
                rejected_prose = tag_buf
    return new_count, partial_kept, bool(all_matches), rejected_prose


def _is_claude_model(model: str) -> bool:
    """Check if a model ID is a Claude/Anthropic model."""
    return bool(model and model.startswith("claude-"))


def _is_gemini_model(model: str) -> bool:
    """Check if a model ID is a Gemini/Google model."""
    return bool(model and (model.startswith("gemini-") or model.startswith("models/gemini")))


